<script setup lang="ts">
import { CalendarDays, Clock3, UsersRound, Equal, AlertCircle, Plus, Printer, QrCode } from '@lucide/vue'
import { formatHours, monthLabel } from '../domain/calendar'
import { clockLabel, planShifts, shiftHours } from '../domain/shifts'
const w = useWorkspace(), newMonth = ref(false)
const total = computed(() => w.summaries.value.reduce((n, r) => n + r.knownHours, 0))
const filled = computed(() => w.summaries.value.reduce((n, r) => n + r.workDays + r.offDays + r.leaveDays + r.notStartedDays, 0))
const currentErrors = computed(() => w.issues.value.filter(i => !i.historical && i.severity === 'error'))
const chartMax = computed(() => Math.max(1, ...w.summaries.value.map(r => r.knownHours)))
const codes = computed(() => w.data.value && w.plan.value ? planShifts(w.data.value, w.plan.value).filter(s => ['PI', 'SI', 'NI', 'PSI', 'MI'].includes(s.code)) : [])
const activeDoctors = computed(() => w.data.value?.doctors.filter(d => d.active).length ?? 0)
</script>

<template>
  <PageHeading title="Ringkasan dinas" subtitle="Pantau jadwal, pemerataan jam, dan kehadiran tim pelayanan." eyebrow="Ruang kerja tim"><MonthSelect /><button v-if="w.canEdit.value" class="btn btn-secondary" @click="newMonth = true"><Plus :size="15" />Bulan baru</button></PageHeading>
  <section class="app-hero mb-7 grid gap-7 overflow-hidden rounded-[1.6rem] p-6 text-ink sm:p-8 xl:grid-cols-[1fr_auto] xl:items-center">
    <div><p class="text-[11px] font-medium tracking-widest text-brand-700">MANAJEMEN DINAS DOKTER</p><h2 class="mt-4 max-w-xl text-3xl leading-tight font-semibold tracking-tight sm:text-4xl">Jadwal jelas.<br />Pelayanan terarah.</h2><p class="mt-4 max-w-xl text-sm leading-relaxed text-brand-800">Jadwal bulanan, beban kerja, dan catatan kehadiran dalam satu ruang kerja yang mudah digunakan.</p><div class="mt-6 flex flex-wrap gap-3"><NuxtLink to="/jadwal" class="btn btn-lime"><CalendarDays :size="16" />Buka jadwal</NuxtLink><NuxtLink to="/absen" class="btn border border-brand-200 bg-white text-brand-800 hover:bg-brand-50"><QrCode :size="16" />Buka absensi</NuxtLink></div></div>
    <div class="grid grid-cols-2 gap-3 xl:w-72 xl:grid-cols-1"><div class="rounded-2xl border border-brand-100 bg-white/85 p-5"><p class="text-[10px] font-medium tracking-widest text-slate-600">TIM AKTIF</p><p class="mt-3 text-4xl font-medium tracking-tight text-brand-700">{{ activeDoctors }}<span class="ml-2 text-sm text-brand-800">dokter</span></p></div><div class="rounded-2xl border border-brand-100 bg-white/85 p-5"><p class="text-[10px] font-medium tracking-widest text-slate-600">PERIODE TERPILIH</p><p class="mt-3 text-lg font-medium">{{ monthLabel(w.activeMonth.value) }}</p><p class="mt-2 text-[11px] text-slate-600">{{ w.plan.value ? w.plan.value.locked ? 'Jadwal sudah dikunci' : 'Draf dapat ditinjau' : 'Jadwal belum tersedia' }}</p></div></div>
  </section>
  <template v-if="w.plan.value">
    <div class="mb-7 grid grid-cols-2 gap-3 xl:grid-cols-4 xl:gap-5"><div v-for="card in [{ label: 'Dokter dalam jadwal', value: w.summaries.value.length, unit: 'orang', icon: UsersRound, note: `${w.summaries.value.filter(r => r.doctor.unit === 'anak').length} khusus ruang anak` }, { label: 'Total jam terjadwal', value: formatHours(total), unit: 'jam', icon: Clock3, note: `${filled} isian dinas tercatat` }, { label: 'Selisih jam rotasi penuh', value: formatHours(w.balance.value.spread), unit: 'jam', icon: Equal, note: `${w.balance.value.rows.length} dokter dengan ketersediaan sama` }, { label: 'Perlu penyesuaian', value: currentErrors.length, unit: 'catatan', icon: AlertCircle, note: 'Periksa sebelum jadwal ditetapkan' }]" :key="card.label" class="panel p-4 sm:p-5"><div class="mb-5 flex items-center justify-between gap-2"><p class="text-xs leading-relaxed text-slate-500">{{ card.label }}</p><span class="rounded-xl bg-brand-50 p-2 text-brand-700"><component :is="card.icon" :size="16" /></span></div><p class="flex flex-wrap items-baseline gap-1.5 text-3xl leading-none font-semibold tracking-tight tabular-nums">{{ card.value }}<span class="text-xs font-normal text-slate-500">{{ card.unit }}</span></p><p class="mt-3 text-[11px] leading-relaxed text-slate-500">{{ card.note }}</p></div></div>
    <div class="grid gap-6 xl:grid-cols-[1.5fr_1fr]">
      <section class="panel overflow-hidden"><div class="flex items-center justify-between gap-3 border-b border-slate-100 px-6 py-5"><div><h2 class="text-sm font-semibold">Jam kerja per dokter</h2><p class="mt-1 text-xs text-slate-500">{{ monthLabel(w.activeMonth.value) }} · dihitung dari jadwal</p></div><NuxtLink to="/rekap" class="text-xs font-semibold text-brand-700">Lihat rekap</NuxtLink></div><div class="space-y-5 p-6"><div v-for="(r, i) in w.summaries.value" :key="r.doctor.id" class="grid grid-cols-[105px_1fr_42px] items-center gap-3 sm:grid-cols-[140px_1fr_52px]"><div class="flex items-center gap-2.5"><span class="hidden h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-slate-50 text-[10px] font-semibold text-slate-500 sm:flex">{{ String(i + 1).padStart(2, '0') }}</span><div class="min-w-0"><p class="truncate text-xs font-medium">{{ r.doctor.name }}</p><p v-if="!r.comparable" class="mt-1 text-[10px] text-slate-500">{{ r.doctor.unit === 'anak' ? 'Ruang anak' : r.leaveDays ? `${r.leaveDays} hari cuti` : 'Ketersediaan berbeda' }}</p></div></div><div class="h-2.5 overflow-hidden rounded-full bg-slate-100"><div class="h-full rounded-full" :class="r.comparable ? 'bg-brand-500' : 'bg-lime-soft'" :style="{ width: `${r.knownHours / chartMax * 100}%` }" /></div><p class="text-right text-xs font-semibold tabular-nums">{{ formatHours(r.totalHours) }}</p></div></div><p class="border-t border-slate-100 bg-slate-50/60 px-6 py-4 text-[11px] leading-relaxed text-slate-500">Pemerataan membandingkan dokter rotasi dengan ketersediaan sebulan penuh. Cuti, dokter baru, dan ruang anak dihitung sesuai dinasnya.</p></section>
      <section class="panel p-6"><div class="mb-5 flex items-center justify-between"><h2 class="text-sm font-semibold">Pemeriksaan jadwal</h2><span class="tag bg-slate-100 text-slate-600">{{ w.issues.value.length }} catatan</span></div><IssueList :issues="w.issues.value" :limit="5" /><NuxtLink to="/jadwal" class="btn btn-secondary mt-5 w-full">Periksa jadwal</NuxtLink></section>
    </div>
    <div class="mt-6 grid gap-6 lg:grid-cols-[1.5fr_1fr]"><section class="panel p-6"><div class="mb-5 flex items-center justify-between"><h2 class="text-sm font-semibold">Jam dinas bulan ini</h2><NuxtLink to="/kode-dinas" class="text-xs font-semibold text-brand-700">Semua kode</NuxtLink></div><div class="grid grid-cols-2 gap-3 sm:grid-cols-3 xl:grid-cols-5"><div v-for="s in codes" :key="s.code" class="rounded-xl border border-slate-100 p-3"><p class="text-sm font-semibold text-brand-700">{{ s.code }}</p><p class="mt-2 text-[11px] text-slate-500">{{ clockLabel(s) }}</p><p class="mt-2 text-xs font-semibold">{{ shiftHours(s) }} jam</p></div></div></section><section class="rounded-2xl border border-brand-200 bg-brand-50 p-6"><Printer :size="23" class="text-brand-700" /><h2 class="mt-4 text-lg font-semibold">Jadwal siap disahkan.</h2><p class="mt-3 text-sm leading-relaxed text-brand-800">Cetak jadwal lengkap dengan legenda jam serta ruang tanda tangan direktur dan kepala seksi pelayanan.</p><NuxtLink to="/cetak" class="btn btn-primary mt-5">Pratinjau cetak</NuxtLink></section></div>
  </template>
  <section v-else class="panel p-10 text-center"><CalendarDays class="mx-auto mb-4 text-brand-600" :size="30" /><h2 class="text-lg font-semibold">Mulai dengan jadwal pertama</h2><p class="mt-2 text-sm text-slate-500">Periksa daftar dokter dan jam dinas, lalu pilih bulan yang ingin disusun.</p><button v-if="w.canEdit.value" class="btn btn-primary mt-6" @click="newMonth = true"><Plus :size="16" />Buat jadwal</button><NuxtLink v-if="w.isAdmin.value" to="/pengaturan" class="btn btn-secondary mt-6 ml-2">Impor jadwal</NuxtLink></section>
  <NewMonthModal v-if="newMonth" @close="newMonth = false" />
</template>
